    async def receipt_create_shipment_async(
        self,
        input: ReceiptCreateShipmentInput,
        shop_id: str,
        receipt_id: str,
    ) -> dict[str, Any] | None:
        """
        Create a Shipment Receipt

        Submits tracking information for a shop receipt, which creates a shop
        receipt Shipment entry for the given receipt ID. Each time you
        successfully submit tracking info, Etsy sends a notification email to
        the buyer User. When send BCC is true, Etsy sends shipping
        notifications to the seller as well. When tracking code and carrier
        name aren't sent, the receipt is marked as shipped only.
        """
        request_url = (
            f"{self._connection_runtime_url}"
            f"/shops"
            f"/{quote(str(shop_id), safe='')}"
            f"/receipts"
            f"/{quote(str(receipt_id), safe='')}"
            f"/tracking"
        )

        response = await self.http_client.send_async(
            "POST", request_url, body=input
        )

        if not (200 <= response.status < 300):
            raise ConnectorException(
                "POST",
                request_url,
                response.status,
                response.text,
            )

        if not response.text:
            return None

        return json.loads(response.text)

